package Operators;

public class Assignment4 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int num = 20;

		num += 5;
		System.out.println("Adds and assigns: " + (num)); //Use all assignment operators

		num -= 3;
		System.out.println("Subtracts and assigns: " + (num));

		num *= 2;
		System.out.println("Multiplies and assigns: " + (num));

		num /= 4;
		System.out.println("Divides and assigns: " + (num));

		num %= 3;
		System.out.println("Modulus and assigns: " + (num));

	}

}
